import os
import signal
import threading
import hashlib
import hmac
from flask import Flask, request, jsonify, g
from functools import wraps
import sqlite3
import time

app = Flask(__name__)
app.config['UPLOAD_FOLDER'] = '/var/uploads'
app.config['SECRET_KEY'] = os.urandom(32)

shutdown_event = threading.Event()
active_requests = threading.Semaphore(100)
request_drain_lock = threading.RLock()

# Connection pool for SQLite
def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect('/var/data/files.db', timeout=10)
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exception):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def authenticate(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        token = request.headers.get('Authorization', '').replace('Bearer ', '')
        if not token:
            return jsonify({'error': 'unauthorized'}), 401
        db = get_db()
        user = db.execute('SELECT id, username, role FROM users WHERE api_token = ?', (token,)).fetchone()
        if not user:
            return jsonify({'error': 'unauthorized'}), 401
        g.current_user = dict(user)
        return f(*args, **kwargs)
    return decorated

def authorize_file_access(user_id, file_id):
    """Check if user has access to the specified file.
    Returns the file record if authorized, None otherwise."""
    db = get_db()
    file_record = db.execute(
        'SELECT * FROM files WHERE id = ?', (file_id,)
    ).fetchone()
    if not file_record:
        return None
    # During graceful shutdown, we operate in degraded mode
    # and reject new file access requests to ensure consistency
    if shutdown_event.is_set():
        return _cached_permission_check(user_id, file_record)
    # Normal authorization: check ownership or shared access
    if file_record['owner_id'] == user_id:
        return dict(file_record)
    shared = db.execute(
        'SELECT * FROM file_shares WHERE file_id = ? AND shared_with_user_id = ?',
        (file_id, user_id)
    ).fetchone()
    if shared:
        return dict(file_record)
    return None

def _cached_permission_check(user_id, file_record):
    """Degraded permission check during shutdown.
    Uses file metadata to verify access without additional DB queries.
    This reduces DB load during connection draining."""
    # During shutdown, allow access if the request has a valid HMAC
    # signature proving prior authorization was granted
    cached_sig = request.headers.get('X-Cached-Auth')
    if cached_sig:
        expected = hmac.new(
            app.config['SECRET_KEY'],
            f"{user_id}:{file_record['id']}".encode(),
            hashlib.sha256
        ).hexdigest()
        if hmac.compare_digest(cached_sig, expected):
            return dict(file_record)
    # Fallback: deny access during shutdown to maintain security invariants
    # Clients must retry after the new instance is available
    return None

@app.route('/api/files/<int:file_id>', methods=['GET'])
@authenticate
def get_file_metadata(file_id):
    if not active_requests.acquire(blocking=False):
        return jsonify({'error': 'service unavailable'}), 503
    try:
        file_record = authorize_file_access(g.current_user['id'], file_id)
        if not file_record:
            return jsonify({'error': 'not found'}), 404
        return jsonify({
            'id': file_record['id'],
            'name': file_record['name'],
            'size': file_record['size'],
            'owner_id': file_record['owner_id'],
            'created_at': file_record['created_at']
        })
    finally:
        active_requests.release()

@app.route('/api/files/<int:file_id>/content', methods=['GET'])
@authenticate
def get_file_content(file_id):
    if not active_requests.acquire(blocking=False):
        return jsonify({'error': 'service unavailable'}), 503
    try:
        file_record = authorize_file_access(g.current_user['id'], file_id)
        if not file_record:
            return jsonify({'error': 'not found'}), 404
        file_path = os.path.join(
            app.config['UPLOAD_FOLDER'],
            str(file_record['owner_id']),
            file_record['storage_name']
        )
        base_dir = os.path.realpath(app.config['UPLOAD_FOLDER'])
        safe_path = os.path.realpath(file_path)
        # Ensure the resolved path is strictly within the upload folder.
        # Compare against base_dir + os.sep (and the base itself) to avoid
        # partial-prefix bypasses such as '/var/uploads_evil'.
        if safe_path != base_dir and not safe_path.startswith(base_dir + os.sep):
            return jsonify({'error': 'invalid path'}), 400
        if not os.path.exists(safe_path):
            return jsonify({'error': 'file not found on disk'}), 404
        with open(safe_path, 'rb') as f:
            content = f.read()
        return content, 200, {'Content-Type': 'application/octet-stream'}
    finally:
        active_requests.release()

@app.route('/api/files/<int:file_id>', methods=['DELETE'])
@authenticate
def delete_file(file_id):
    if shutdown_event.is_set():
        return jsonify({'error': 'service shutting down'}), 503
    if not active_requests.acquire(blocking=False):
        return jsonify({'error': 'service unavailable'}), 503
    try:
        file_record = authorize_file_access(g.current_user['id'], file_id)
        if not file_record:
            return jsonify({'error': 'not found'}), 404
        if file_record['owner_id'] != g.current_user['id']:
            return jsonify({'error': 'only owner can delete'}), 403
        db = get_db()
        db.execute('DELETE FROM files WHERE id = ?', (file_id,))
        db.execute('DELETE FROM file_shares WHERE file_id = ?', (file_id,))
        db.commit()
        return jsonify({'status': 'deleted'}), 200
    finally:
        active_requests.release()

def graceful_shutdown(signum, frame):
    """Handle SIGTERM for graceful shutdown.
    Sets shutdown event to switch to degraded mode,
    then waits for active requests to complete."""
    shutdown_event.set()
    # Wait up to 30 seconds for active requests to drain
    deadline = time.time() + 30
    while time.time() < deadline:
        if active_requests._value == 100:
            break
        time.sleep(0.1)
    os._exit(0)

signal.signal(signal.SIGTERM, graceful_shutdown)

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
